// src/jsx/Chat/Private/PrivateChat.MessageComponents.jsx
import React from "react";
import { linkifyAndEmojify, formatTime, getMessageUrl } from "../../../js/Chat/PrivateChat.helpers";

export function MessageBubble({ m, isMe, sender, ...props }) {
  const html = linkifyAndEmojify(m.text || "");
  const url = getMessageUrl(m.url);

  return (
    <div style={{ display: "flex", justifyContent: isMe ? "flex-end" : "flex-start", marginBottom: 10 }}>
      {!isMe && (
        <img src={sender?.avatarUrl} alt="" style={{ width: 36, height: 36, borderRadius: 18, marginRight: 8 }} />
      )}

      <div className={`msg ${isMe ? "me" : "other"}`} style={{ maxWidth: 480 }}>
        {m.type === "image" && <img src={url} style={{ width: "100%", borderRadius: 8 }} />}
        {m.type === "video" && <video src={url} controls style={{ width: "100%", borderRadius: 8 }} />}
        {m.type === "audio" && <audio src={url} controls />}
        {m.type === "gif" && <img src={url} style={{ width: "100%", borderRadius: 8 }} />}
        {m.type === "file" && <a href={url}>{url.split("/").pop()}</a>}

        {m.text && (
          <div
            className="msg-text"
            style={{ whiteSpace: "pre-wrap", lineHeight: "1.45", fontSize: "15px" }}
            dangerouslySetInnerHTML={{ __html: html }}
          />
        )}

        <div className="hora" style={{ fontSize: 11, marginTop: 6, textAlign: "right" }}>
          {formatTime(m.createdAt)} {m.edited && "(editada)"}
        </div>
      </div>
    </div>
  );
}
